+/**
+ * @file
+ * Call-stack panel: column layout, model build, frame selection.
+ */
+
+#include "lua_debugger_stack.h"
+
+#include <QAbstractItemView>
+#include <QClipboard>
+#include <QColor>
+#include <QFileInfo>
+#include <QGuiApplication>
+#include <QHeaderView>
+#include <QItemSelectionModel>
